import {
    Table,
    ChoiceColumn,
    GuidColumn,
    ReferenceColumn,
    DomainIdColumn,
    DomainPathColumn,
    StringColumn,
    IntegerColumn,
    DateTimeColumn,
    GenericColumn,
} from '../../db'

export const sys_flow_data = Table({
    attributes: {
        no_audit_delete: true,
    },
    label: 'Flow Data',
    name: 'sys_flow_data',
    schema: {
        definition: ReferenceColumn({
            label: 'Definition',
            readOnly: true,
            referenceTable: 'sys_flow_data_definition',
        }),
        vars: GenericColumn({
            columnType: 'glide_var',
            label: 'Variables',
            referenceTable: 'sys_flow_data_var',
            attributes: {
                model_field: 'definition',
            },
        }),
        assignment_group: ReferenceColumn({
            label: 'Assignment Group',
            referenceTable: 'sys_user_group',
        }),
        assigned_to: ReferenceColumn({
            label: 'Assigned To',
            referenceTable: 'sys_user',
        }),
        playbook_context: ReferenceColumn({
            label: 'Playbook Context',
            readOnly: true,
            referenceTable: 'sys_pd_context',
        }),
        activity_id: GuidColumn({
            label: 'Activity ID',
            readOnly: true,
        }),
        state: ChoiceColumn({
            label: 'State',
            default: 'PENDING',
            choices: {
                CANCELLED: {
                    label: 'Cancelled',
                },
                COMPLETE: {
                    label: 'Complete',
                },
                ERROR: {
                    label: 'Error',
                },
                IN_PROGRESS: {
                    label: 'In Progress',
                },
                PENDING: {
                    label: 'Pending',
                },
                READY: {
                    label: 'Ready',
                },
                SCHEDULED: {
                    label: 'Scheduled',
                },
                SKIPPED: {
                    label: 'Skipped',
                },
            },
        }),
        sys_id: GuidColumn({
            label: 'Sys ID',
            primary: true,
        }),
        sys_domain: DomainIdColumn({
            default: 'global',
            label: 'Domain',
            readOnly: true,
        }),
        sys_domain_path: DomainPathColumn({
            default: '/',
            label: 'Domain Path',
        }),
        sys_created_on: DateTimeColumn({
            label: 'Created',
        }),
        sys_created_by: StringColumn({
            label: 'Created by',
        }),
        sys_updated_on: DateTimeColumn({
            label: 'Updated',
        }),
        sys_updated_by: StringColumn({
            label: 'Updated by',
        }),
        sys_mod_count: IntegerColumn({
            label: 'Updates',
        }),
    },
})
